          .asFunction<int Function(ffi.Pointer<ffi.Void>, int, int)>();
  GdkKeyMatch matches(int keyval, GdkModifierType modifiers) {
    return GdkKeyMatch.fromValue(
      _gdkKeyEventMatches(this.handle, keyval, modifiers.value),
    );
  }
}
